package uk.ac.ravensbourne.casevault.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="cases") public class CaseRecord { @Id private UUID id; @ManyToOne(optional=false) @JoinColumn(name="organisation_id") private Organisation organisation; @Column(nullable=false) private String title; @Column(nullable=false) private String description; @Enumerated(EnumType.STRING) private Category category; @Enumerated(EnumType.STRING) private Severity severity; @Enumerated(EnumType.STRING) private CaseStatus status; @ManyToOne @JoinColumn(name="owner_analyst_id") private UserAccount ownerAnalyst; @ManyToOne(optional=false) @JoinColumn(name="created_by") private UserAccount createdBy; @Version private long version; private Instant createdAt=Instant.now(),updatedAt=Instant.now(),retentionUntil,deletedAt; protected CaseRecord(){} public CaseRecord(UUID id,Organisation org,String title,String description,Category category,Severity severity,UserAccount creator){this.id=id;this.organisation=org;this.title=title;this.description=description;this.category=category;this.severity=severity;this.status=CaseStatus.NEW;this.createdBy=creator;} public UUID getId(){return id;} public Organisation getOrganisation(){return organisation;} public String getTitle(){return title;} public String getDescription(){return description;} public Category getCategory(){return category;} public Severity getSeverity(){return severity;} public CaseStatus getStatus(){return status;} public void transitionTo(CaseStatus next){this.status=next;} }
